using System;
using System.Globalization;

namespace IDLab.Core.Chemistry
{
    /// <summary>
    /// Registers the large chemical catalogue (ionic compounds, acids, elements, molecular and organic compounds)
    /// generated by <c>desktop/tools/gen_chemicals.py</c> into <see cref="ChemicalData"/>. Rows marked as patches add
    /// catalogue metadata (Turkish name, aliases, ionic composition) to the hand-tuned substances defined in
    /// <see cref="SubstanceDatabase.CreateDefault"/> without changing their physical data.
    /// </summary>
    public static class ChemicalLibrary
    {
        private const int Fields = 40;

        public static void Register(SubstanceDatabase db)
        {
            var ci = CultureInfo.InvariantCulture;
            foreach (var raw in ChemicalData.Rows.Split('\n'))
            {
                var line = raw.TrimEnd('\r');
                if (line.Length == 0 || line[0] == '#') continue;
                var f = line.Split('|');
                if (f.Length != Fields) throw new FormatException($"Chemical row has {f.Length} fields: {line}");

                double D(int i) => f[i].Length == 0 ? 0 : double.Parse(f[i], ci);
                int I(int i) => f[i].Length == 0 ? 0 : int.Parse(f[i], ci);
                string S(int i) => f[i].Length == 0 ? null : f[i];

                bool patch = f[1] == "1";
                Substance s;
                if (patch)
                {
                    if (!db.TryGet(f[0], out s)) continue;
                }
                else
                {
                    s = new Substance
                    {
                        Id = f[0], Name = f[2], Formula = f[4],
                        Kind = (SubstanceKind)Enum.Parse(typeof(SubstanceKind), f[7]),
                        Phase = f[8] == "L" ? SubstancePhase.Liquid : f[8] == "S" ? SubstancePhase.Solid : SubstancePhase.Aqueous,
                        IsGas = f[9] == "1", Soluble = f[10] == "1",
                        Form = (SolidForm)Enum.Parse(typeof(SolidForm), f[11]),
                        Hazards = (Hazard)I(12), MolarMass = D(13), Density = D(14) > 0 ? D(14) : 1.0,
                        BoilingPointC = f[15].Length == 0 ? double.NaN : D(15),
                        Protons = I(16), Hydroxides = I(17), Ka = D(18), Kb = D(19),
                        ConjugateId = S(20), ConjugateCount = Math.Max(1, I(21)),
                        MolecularSpeciesId = S(35), Hidden = f[36] == "1", FormsComplex = f[37] == "1",
                        SpecificHeat = D(38) > 0 ? D(38) : 1500, LatentHeatVaporization = D(39),
                    };
                    if (f[31].Length > 0) s.Color = ColorRGBA.FromHex(uint.Parse(f[31], NumberStyles.HexNumber, ci), (float)D(32));
                    s.TintStrength = D(33);
                    foreach (var ion in f[34].Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                        int star = ion.IndexOf('*');
                        s.Ions.Add(star < 0 ? new IonPart(ion) : new IonPart(ion.Substring(0, star), int.Parse(ion.Substring(star + 1), ci)));
                    }
                }

                // Catalogue + composition metadata (applies to patches too).
                s.NameTr = S(3) ?? s.NameTr;
                if (f[5].Length > 0)
                {
                    foreach (var a in f[5].Split(';'))
                    {
                        if (a.Length > 0 && !s.Aliases.Contains(a)) s.Aliases.Add(a);
                    }
                }

                s.Category = S(6) ?? s.Category;
                if (f[22].Length > 0)
                {
                    s.CationKey = f[22]; s.CationCharge = I(23); s.CationCount = I(24);
                    s.AnionKey = f[25]; s.AnionCharge = I(26); s.AnionCount = I(27);
                }

                s.ElementSymbol = S(28) ?? s.ElementSymbol;
                if (s.SaltAcidKa <= 0 && D(29) > 0)
                {
                    s.SaltAcidKa = D(29);
                    s.SaltAcidCount = Math.Max(1, I(30));
                }

                if (patch && s.ConjugateId == null && S(20) != null)
                {
                    s.ConjugateId = S(20);
                    s.ConjugateCount = Math.Max(1, I(21));
                }

                if (patch) db.Index(s);
                else db.Register(s);
            }
        }
    }
}
